  var SITES_SCAD = [{"id": "luthadel", "name": "Luthadel", "lat": 70.0, "lon": 0.0, "books": [2], "desc": "Capital of the Final Empire, walled, with eight gates named for metals, and the River Channerel running through it. It was built over the Well of Ascension.", "until": 6}, {"id": "kredikshaw", "name": "Kredik Shaw", "lat": 70.01, "lon": 0.0, "books": [2], "desc": "The Lord Ruler’s palace, the Hill of a Thousand Spires, where Vin finally faces him.", "until": 6}, {"id": "well", "name": "Well of Ascension", "lat": 70.01, "lon": 0.0, "books": [2], "desc": "Preservation’s perpendicularity: a small pool of glowing power in a cavern beneath the palace. Rashek moved it here from the Terris mountains.", "until": 6}, {"id": "fellise", "name": "Fellise", "lat": 69.88, "lon": -0.42, "books": [2], "desc": "A genteel town an hour from Luthadel, where the crew set up the Renoux mansion.", "until": 6}, {"id": "hathsin", "name": "Pits of Hathsin", "lat": 74.12, "lon": -1.85, "books": [2], "desc": "The atium mines, worked by skaa prisoners, where Kelsier survived and Snapped. Ruin’s pool lay below them.", "until": 6}, {"id": "homeland", "name": "The kandra Homeland", "lat": 74.27, "lon": -0.8, "books": [2], "desc": "The kandra’s cavern city near the Pits, where the Lord Ruler’s atium was hidden.", "until": 6}, {"id": "arguois", "name": "Arguois caverns", "lat": 72.95, "lon": -2.22, "books": [2], "desc": "Caves north of Luthadel where Kelsier’s skaa army trained.", "until": 6}, {"id": "tyrian", "name": "Lake Tyrian and Mount Tyrian", "lat": 69.47, "lon": -9.11, "books": [2], "desc": "A large lake west of Luthadel with an ashmount rising from its middle.", "sea": true, "until": 6}, {"id": "urteau", "name": "Urteau", "lat": 74.23, "lon": 15.6, "books": [2], "desc": "Capital of the Northern Dominance and the Ventures’ seat, its streets drained canals. Held by rebel skaa in The Hero of Ages.", "until": 6}, {"id": "tremredare", "name": "Tremredare", "lat": 67.8, "lon": -27.75, "books": [2], "desc": "The Western Dominance’s old capital, a market city of luxuries.", "until": 6}, {"id": "fadrex", "name": "Fadrex City", "lat": 67.46, "lon": -19.98, "books": [2], "desc": "A western capital ringed by red rock formations, guarding one of the Lord Ruler’s storage caches. Besieged in The Hero of Ages.", "until": 6}, {"id": "statlin", "name": "Statlin City", "lat": 68.88, "lon": 9.27, "books": [2], "desc": "An eastern mining city with a storage cache.", "until": 6}, {"id": "conventical", "name": "Conventical of Seran", "lat": 58.62, "lon": 4.7, "books": [2], "desc": "A windowless, steel-plated fortress of the Steel Inquisitors in a crater south-east of Luthadel.", "until": 6}, {"id": "vetitan", "name": "Vetitan", "lat": 67.83, "lon": -0.96, "books": [2], "desc": "A southern farming and mining town with a cache under its Ministry building.", "until": 6}, {"id": "lekal", "name": "Lekal City", "lat": 64.34, "lon": -6.69, "books": [2], "desc": "A southern capital on the Channerel, destroyed by lava near the end.", "until": 6}, {"id": "tathingdwen", "name": "Tathingdwen", "lat": 83.38, "lon": 15.1, "books": [2], "desc": "Capital of the Terris people in the far north, seat of the Keepers’ Synod. Burned by koloss.", "until": 6}, {"id": "islands", "name": "The Southern Islands", "lat": 57.33, "lon": -12.31, "books": [2], "desc": "Islands across the Southern Sea from the Final Empire.", "until": 6}, {"id": "elendel", "name": "Elendel", "lat": 1.0, "lon": 0.0, "books": [6, 7, 10], "desc": "Capital of the Basin, split into eight octants by canals around the Field of Rebirth, on Hammondar Bay. The equator runs close by and the prime meridian through it.", "since": 6}, {"id": "steinel", "name": "Steinel", "lat": 1.09, "lon": 1.81, "books": [6], "desc": "A city due east of Elendel along the Irongate.", "since": 6}, {"id": "rashekin", "name": "Rashekin", "lat": 3.1, "lon": 2.39, "books": [6, 10], "desc": "A city north-east of Elendel on the railway toward the Faleast Range, outside Elendel’s control.", "since": 6}, {"id": "tathingdwel", "name": "Tathingdwel", "lat": 4.04, "lon": -0.94, "books": [10], "desc": "A Terris city in the foothills of the Channerel Range.", "since": 6}, {"id": "drypost", "name": "Drypost", "lat": 4.83, "lon": 1.96, "books": [6, 10], "desc": "A rail city far north-east of Elendel, on the line to the Northern Roughs.", "since": 6}, {"id": "doriel", "name": "Doriel", "lat": -0.59, "lon": 1.59, "books": [10], "desc": "The biggest rail junction outside Elendel, built where an ashmount once stood.", "since": 6}, {"id": "bilming", "name": "Bilming", "lat": -1.17, "lon": -0.8, "books": [10], "desc": "The Basin’s other great port, on a peninsula, with the tower called the Shaw. The Set’s stronghold in The Lost Metal.", "since": 6}, {"id": "newseran", "name": "New Seran", "lat": -2.79, "lon": 2.61, "books": [6], "desc": "A terraced waterfall city with gondolas on the southern edge of the Basin.", "since": 6}, {"id": "dulsing", "name": "Dulsing", "lat": -2.3, "lon": 3.08, "books": [6], "desc": "A remote farming village at the foot of the Seran Range.", "since": 6}, {"id": "bandstemple", "name": "Temple of the Bands of Mourning", "lat": -2.69, "lon": 3.47, "books": [6], "desc": "A fieldstone fortress near the highest Seran peaks, with trapped corridors guarding the Bands.", "since": 6}, {"id": "truemadil", "name": "True Madil", "lat": 6.64, "lon": 1.96, "books": [6], "desc": "The largest city of the Northern Roughs, where two rivers meet; the only railhead out there.", "since": 6}, {"id": "weathering", "name": "Weathering", "lat": 6.93, "lon": -0.87, "books": [6], "desc": "A dusty grassland town in the Roughs, Waxillium’s base for twenty years.", "since": 6}, {"id": "fardorest", "name": "Far Dorest", "lat": 8.01, "lon": 3.43, "books": [6], "desc": "A large Northern Roughs city.", "since": 6}, {"id": "tyriansea", "name": "The Tyrian Sea", "lat": 8.53, "lon": 0.29, "books": [6], "desc": "The sea in the Northern Roughs that took the place of Lake Tyrian.", "sea": true, "since": 6}, {"id": "luthruins", "name": "Where Luthadel stood", "lat": 8.81, "lon": 3.5, "books": [6, 10], "desc": "Our estimate of where Luthadel’s ruins lie in the remade world, from overlaying the two maps; no book map marks it.", "since": 6}, {"id": "newtremredare", "name": "New Tremredare", "lat": -3.89, "lon": 3.8, "books": [10], "desc": "The Festival City on the Sea of Lennes, at the edge of the Conrad Delta in the Southern Roughs.", "since": 6}, {"id": "bluepool", "name": "A blue pool in the southern mountains", "lat": -3.77, "lon": 5.22, "books": [10], "desc": "A broadsheet in The Lost Metal reports a perfectly blue pool here; it may be Harmony’s perpendicularity, which canon places only in the far south.", "since": 6}, {"id": "southcontinent", "name": "The Southern Continent", "lat": -72.0, "lon": 10.0, "books": [6, 10], "desc": "Near the south pole, across a wide ocean: colder and harsher than the Basin, with towers and flying craft. Home of the Malwish and other southern peoples, revealed in The Bands of Mourning.", "since": 6}];

