  var SITES_TALDAIN = [{"id":"kraeda","name":"Mount KraeDa","lat":0,"lon":0,"books":[7],"desc":"A lone mountain at the exact centre of Dayside, with the sun directly overhead. Kerla’s sand surrounds it, and the Diem hold their trials at its foot."},{"id":"kerla","name":"Kerla","lat":5,"lon":-25,"books":[7],"desc":"A sand ‘lake’ with water just beneath and vines under the surface, ringing KraeDa and covering much of Kerzta."},{"id":"kezare","name":"Kezare","lat":-33,"lon":3,"books":[7],"desc":"Lossand’s capital, on river islands where the Ry’DoAli meets the Nor’Tallon. Home of the Diem, the order of Sand Masters, in a building carved from one block of white sandstone."},{"id":"kerkedasha","name":"Ker Kedasha","lat":-30,"lon":-34,"books":[7],"desc":"The capital of Kerzta, the largest and strongest Dayside nation, due west of Kezare."},{"id":"lraezare","name":"Lraezare","lat":-64.5,"lon":4.5,"books":[7],"desc":"A port at the mouth of the Ry’DoAli on the south coast, where the sun sits low on the horizon."},{"id":"nortallon","name":"Nor’Tallon","lat":-28,"lon":52,"books":[7],"desc":"Capital of Tallon, in the mountains that wall off the eastern Rim Kingdoms."},{"id":"deepsand","name":"The deep sand","lat":-28,"lon":30,"books":[7],"desc":"Uninhabited deep desert east of Lossand, home of the deep sandlings."},{"id":"borderocean","name":"The Border Ocean and Terminal Storm","lat":0,"lon":90,"sea":true,"books":[7],"desc":"The ocean ring along the line between day and night, with a permanent storm along its middle that makes crossings deadly."},{"id":"darkside","name":"Darkside","lat":0,"lon":-170,"books":[7],"desc":"The night face, always turned to the dim Eye of Ridos and lit in ultraviolet twilight. Khriss comes from the nation of Elis here, which resists the Dynasty. Its shape is our placeholder."}];
