  var SITES_FIRSTSUN = [{"id":"patji","name":"Patji","lat":-5.0,"lon":-0.5,"books":[7,12],"desc":"The Father island, the largest of the Pantheon: wedge-shaped, with knife-edged peaks and a jungle that punishes every mistake. Aviar must visit it to gain their talents. Dusk traps here."},{"id":"patjiseye","name":"Patji’s Eye","lat":-4.5,"lon":1.75,"books":[12],"desc":"A green-tinted lake of not-quite-water in a canyon toward Patji’s eastern peak, holding glowing worms. It is a perpendicularity, and Dusk sails through it into the Emberdark."},{"id":"fort","name":"The Northern Interests fort","lat":-5.75,"lon":-4.25,"books":[7,12],"desc":"A fortified wooden stronghold with cannons at the far end of Patji, where the Ones Above set their machine."},{"id":"sori","name":"Sori","lat":-15.0,"lon":4.5,"books":[7],"desc":"The smallest and tamest island of the Pantheon, closest to home, where young trappers train."},{"id":"homeisles","name":"The Homeisles","lat":-29.5,"lon":20.5,"sea":true,"books":[7,12],"desc":"The tamed islands of the Eelakin, with their cities and reefs, about three weeks’ rowing from the Pantheon. Their layout here is our placeholder."},{"id":"mainland","name":"The mainland","lat":-62.0,"lon":10.0,"books":[7,12],"desc":"A frozen wasteland to the south of the homeisles, with native ravens and no sign of people."}];
