  var SITES_LUMAR = [{"id":"rock","name":"Diggen’s Point (the Rock)","lat":27.3,"lon":0.6,"books":[11],"desc":"A crooked finger of black saltstone in the Emerald Sea, 50 or 60 miles from the green lunagree, with a small town and the duke’s mansion near the top. Tress works here and collects cups."},{"id":"emerald","name":"The Emerald Sea","lat":26.6,"lon":0,"sea":true,"books":[11],"desc":"The green Verdant Sea, Tress’s home sea, piled highest under its moon’s spore-fall."},{"id":"kingsport","name":"Kingsport (Core Archipelago)","lat":38.2,"lon":-13.6,"books":[11],"desc":"Probably the royal city of the Verdant king, in the Core Archipelago far from the Rock. Position is our placeholder."},{"id":"crimson","name":"The Crimson Sea","lat":-26.6,"lon":36,"sea":true,"books":[11],"desc":"Red spores that throw up spike-forests in sudden squalls. The dragon Xisis lies in a lair near its lunagree. It borders the Midnight Sea and is one of the few ways in."},{"id":"midnight","name":"The Midnight Sea","lat":-26.6,"lon":108,"sea":true,"books":[11],"desc":"Black, warm spores, walled in by mountains on four sides; the Sorceress’s domain."},{"id":"sorceress","name":"The Sorceress’s island","lat":-30.0,"lon":76.0,"books":[11],"desc":"A small, suspiciously round island in the Midnight Sea near the Crimson border, with a silver tower that is really a starship."},{"id":"rosesea","name":"The Rose Sea","lat":26.6,"lon":-72,"sea":true,"books":[11],"desc":"A pink, inhabited sea bordering the Emerald."},{"id":"sapphire","name":"The Sapphire Sea","lat":75,"lon":0,"sea":true,"books":[11],"desc":"The blue Zephyr Sea in the north, home of the Islands of Lobu and the Zephyr Islands."},{"id":"lobu","name":"The Islands of Lobu","lat":70.0,"lon":20.0,"books":[11],"desc":"Large islands of the Sapphire Sea with a hunting culture; home of Fort and Salay."}];
