  function attachScenes(worlds) {
    worlds.forEach(function (w) {
      var m = SCENES[w.id]; if (!m || !w.sites) return;
      w.sites.forEach(function (st) { if (m[st.id]) st.scene = m[st.id]; });
    });
  }
